**Step 8: Configure Timeouts and Retries**

```java
// Java RestTemplate with connection pooling and timeouts
@Bean
public RestTemplate restTemplate() {
    HttpComponentsClientHttpRequestFactory factory = new HttpComponentsClientHttpRequestFactory();

    // Connection timeout: 3 seconds
    factory.setConnectTimeout(3000);

    // Read timeout: 10 seconds
    factory.setReadTimeout(10000);

    // Connection pool
    HttpClient httpClient = HttpClientBuilder.create()
        .setMaxConnTotal(100)         // Total connections
        .setMaxConnPerRoute(20)       // Connections per host
        .setConnectionTimeToLive(30, TimeUnit.SECONDS)
        .build();
    factory.setHttpClient(httpClient);

    return new RestTemplate(factory);
}
```

```csharp
// C# HttpClient with timeout
services.AddHttpClient("MemberServiceClient", client =>
{
    client.BaseAddress = new Uri("http://member-service:8080");
    client.Timeout = TimeSpan.FromSeconds(10);
})
.AddPolicyHandler(GetRetryPolicy());  // Polly retry policy

static IAsyncPolicy<HttpResponseMessage> GetRetryPolicy()
{
    return HttpPolicyExtensions
        .HandleTransientHttpError()
        .OrResult(msg => msg.StatusCode == System.Net.HttpStatusCode.NotFound)
        .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
}
```
